"use strict";exports.id=42501,exports.ids=[42501],exports.modules={42501:a=>{a.exports=JSON.parse('{"_status":"machine-draft, needs human review","Back to sign in":"ናብ ምእታው ተመለስ","Book verified healers, readers and cultural services near you or online.":"ዝተረጋገጹ ሓካይም ባህሊ፣ ኣንበብትን ባህላዊ ኣገልግሎታትን ኣብ ጥቓኻ ወይ ብኦንላይን ቈጸራ ሓዝ።","Choose a stronger password.":"ዝሓየለ መሕለፊ ቃል ምረጽ።","Create account":"ሕሳብ ፍጠር","Creating your account…":"ሕሳብካ ይፍጠር ኣሎ…","Forgot password?":"መሕለፊ ቃል ረሲዕካ?","Hide password":"መሕለፊ ቃል ሕባእ","I agree to the":"ይሰማማዕ እየ ምስ","Keep me signed in":"ኣቲኻ ከም ዘለኻ ኣጽንሓኒ","Password":"መሕለፊ ቃል","Pay with telebirr, bank transfer or Chapa, and get updates on Telegram.":"ብtelebirr፣ ብባንኪ ምትሕልላፍ ወይ ብChapa ክፈል፣ ሓበሬታታት ድማ ኣብ Telegram ርኸብ።","Please accept the terms to continue.":"ንምቕጻል በጃኻ ነቲ ውዕላት ተቐበል።","Preferred language":"ዝተመርጸ ቋንቋ","Reset your password":"መሕለፊ ቃልካ ሐድሶ","Run your practice: bookings, clients, remedies, payments and your team.":"ስራሕካ ኣመሓድር፦ ቈጸራታት፣ ዓማዊል፣ መድሃኒታት፣ ክፍሊታትን ጉጅለኻን።","Send reset link":"ናይ ምሕዳስ ሊንክ ስደድ","Show password":"መሕለፊ ቃል ኣርኢ","Sign-ups are paused":"ምዝገባ ንግዚኡ ጠጠው ኢሉ ኣሎ","Signing in with Telegram…":"ብTelegram ይኣቱ ኣሎ…","Signing in…":"ይኣቱ ኣሎ…","Traditional healers and cultural makers, in one trusted place.":"ባህላውያን ሓካይምን ፈጠርቲ ባህልን፣ ኣብ ሓደ እሙን ቦታ።","You\'ll sign in with this. No verification email needed.":"በዚ ኢኻ ክትኣቱ። ናይ ምርግጋጽ ኢመይል ኣየድልን።","terms and privacy policy":"ውዕላትን ፖሊሲ ብሕትውነትን"}')}};